import React from 'react';
import { Sparkles, Brain, ShieldAlert, CheckCircle2, ArrowRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const AIGaugeRing = ({ percentage = 96, color = '#2563EB', size = 56, strokeWidth = 5.5, label }) => {
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div style={{ position: 'relative', width: size, height: size, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
      <svg width={size} height={size} style={{ transform: 'rotate(-90deg)' }}>
        <circle cx={size / 2} cy={size / 2} r={radius} stroke="#E2E8F0" strokeWidth={strokeWidth} fill="transparent" />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          stroke={color}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          fill="transparent"
        />
      </svg>
      <span style={{ position: 'absolute', fontSize: '0.68rem', fontWeight: '900', color: '#0F172A' }}>
        {label || `${Math.round(percentage)}%`}
      </span>
    </div>
  );
};

const AIIntelligenceCard = () => {
  const navigate = useNavigate();

  return (
    <div className="glass-card" style={{ padding: '1.5rem', marginBottom: '1.75rem', background: '#ffffff', borderRadius: '14px', border: '1px solid #E2E8F0' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
        <div>
          <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Sparkles size={20} style={{ color: 'var(--accent-primary)' }} /> AI Predictive Intelligence & RUL Engine
          </h3>
          <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: '600', marginTop: '2px' }}>
            Predictive Machine Health, Failure Probabilities, and Automated Maintenance Diagnostics
          </p>
        </div>
        <button className="btn btn-secondary btn-sm" onClick={() => navigate('/ai-intelligence')}>
          Open AI Matrix <ArrowRight size={14} />
        </button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1.1rem', marginBottom: '1.25rem' }}>
        {/* FLEET HEALTH SCORE */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>FLEET HEALTH SCORE</div>
            <div style={{ fontSize: '1.5rem', fontWeight: '900', color: '#2563EB', marginTop: '2px' }}>96%</div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>Optimal Operational Range</div>
          </div>
          <AIGaugeRing percentage={96} color="#2563EB" />
        </div>

        {/* FAILURE PROBABILITY */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>FAILURE PROBABILITY</div>
            <div style={{ fontSize: '1.5rem', fontWeight: '900', color: '#16A34A', marginTop: '2px' }}>4.2%</div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>Low Risk Threshold (&lt; 15%)</div>
          </div>
          <AIGaugeRing percentage={4.2} max={100} color="#16A34A" label="4.2%" />
        </div>

        {/* REMAINING USEFUL LIFE (RUL) */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>REMAINING USEFUL LIFE (RUL)</div>
            <div style={{ fontSize: '1.5rem', fontWeight: '900', color: '#0F172A', marginTop: '2px' }}>842 <span style={{ fontSize: '0.78rem' }}>Hours</span></div>
            <div style={{ fontSize: '0.72rem', color: '#64748B', marginTop: '3px', fontWeight: '700' }}>Est. ~35 Days Run Time</div>
          </div>
          <AIGaugeRing percentage={84} color="#7C3AED" label="842h" />
        </div>

        {/* CONFIDENCE LEVEL */}
        <div style={{ padding: '1.1rem', background: '#F8FAFC', borderRadius: '10px', border: '1px solid #E2E8F0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            <div style={{ fontSize: '0.74rem', fontWeight: '800', color: '#64748B' }}>CONFIDENCE LEVEL</div>
            <div style={{ fontSize: '1.5rem', fontWeight: '900', color: '#2563EB', marginTop: '2px' }}>99.4%</div>
            <div style={{ fontSize: '0.72rem', color: '#16A34A', marginTop: '3px', fontWeight: '800' }}>XGBoost & LSTM Ensemble</div>
          </div>
          <AIGaugeRing percentage={99.4} color="#2563EB" />
        </div>
      </div>

      {/* AI Diagnostic Detail Banner */}
      <div style={{ padding: '1rem 1.25rem', background: 'rgba(8, 131, 149, 0.08)', borderRadius: '10px', border: '1px solid rgba(8, 131, 149, 0.25)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
        <div>
          <div style={{ fontSize: '0.75rem', fontWeight: '800', color: 'var(--accent-primary)', textTransform: 'uppercase' }}>ROOT CAUSE ANALYSIS & DIAGNOSTICS</div>
          <div style={{ fontSize: '0.9rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '2px' }}>
            LOOM-201 Drive Shaft Bearing Micro-Wear Identified
          </div>
          <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: '2px', fontWeight: '600' }}>
            Recommended Action: Schedule preventive bearing overhaul within 48 hours to avert unplanned downtime.
          </div>
        </div>
        <button className="btn btn-primary btn-sm" onClick={() => navigate('/maintenance')}>
          Dispatch Work Order
        </button>
      </div>
    </div>
  );
};

export default AIIntelligenceCard;
